#include <iostream>
#include <vector>
using namespace std;

const int MAX_V = 10000;

vector<bool> prime(MAX_V + 1, true);

void sieve() {
    prime[0] = prime[1] = false; // 0 and 1 are not prime
    for (int i = 2; i * i <= MAX_V; i++) {
        if (prime[i]) {
            for (int k = i * i; k <= MAX_V; k += i) {
                prime[k] = false;
            }
        }
    }
}

int main() {
    sieve(); // Precompute prime numbers once

    int n;
    while (cin >> n && n != 0) {
        int p1 = 0, q1 = 0;
        for (int i = n; i >= 3; i--) {
            if (prime[i] && prime[i - 2]) {
                q1 = i;
                p1 = i - 2;
                break;
            }
        }
        cout << p1 << " " << q1 << endl;
    }

    return 0;
}

